use vstd::prelude::*;

verus! {

#[verifier(external_body)]
struct Interval {
    start: f32,
    end: f32,
}

/// Laguerre series object type
#[verifier(external_body)]
struct Laguerre {
    coefficients: Vec<f32>,
    domain: Interval,
    window: Interval,
}

fn make_laguerre(coefficients: Vec<f32>) -> Laguerre
    ensures
        // The output's coefficients vector is the same length as the input
        laguerre_coeffs_len(&result) == coefficients.len() &&

        // Each coefficient at index i equals the input coefficient at i
        forall|i: int| 0 <= i < (coefficients.len() as int) ==>
            laguerre_coeff_at(&result, i) == coefficients.get(i as usize).unwrap() &&

        // domain interval is exactly [0.0, 1.0]
        laguerre_domain(&result).start == 0.0 &&
        laguerre_domain(&result).end == 1.0 &&

        // window interval is exactly [0.0, 1.0]
        laguerre_window(&result).start == 0.0 &&
        laguerre_window(&result).end == 1.0
{
    Laguerre {
        coefficients: coefficients,
        domain: Interval {
            start: 0.0,
            end: 1.0,
        },
        window: Interval {
            start: 0.0,
            end: 1.0,
        },
    }
}

/// Specification function to get the length of Laguerre coefficients vector
spec fn laguerre_coeffs_len(l: &Laguerre) -> nat {
    l.coefficients.len() as nat
}

/// Specification function to get the coefficient at index i
spec fn laguerre_coeff_at(l: &Laguerre, i: int) -> f32 {
    l.coefficients.get(i as usize).unwrap()
}

/// Specification function to get the domain interval
spec fn laguerre_domain(l: &Laguerre) -> Interval {
    l.domain
}

/// Specification function to get the window interval
spec fn laguerre_window(l: &Laguerre) -> Interval {
    l.window
}

}
